{
  "sql": "SELECT id, match_id, scorer_player_id, minute, goal_type, assist_player_id, count(*) OVER () AS total_rows FROM world_cup.world_cup.goals WHERE assist_player_id IS NULL ORDER BY id LIMIT 50",
  "datasourceId": "607a1395-869f-4f6e-9a9f-37980472e9c2",
  "rationale": "List the goals that have no assist player recorded, to show the records behind the completeness finding on goals.assist_player_id.",
  "limit": 50
}
